1	/**
2	 * Execute a single Groq run.
3	 *
4	 * Strategy: direct HTTP POST to Groq's OpenAI-compatible
5	 *   https://api.groq.com/openai/v1/chat/completions
6	 * endpoint with stream: true. We accumulate SSE deltas into a single
7	 * assistant reply, append (user prompt + assistant reply) to the stored
8	 * session history, and return an AdapterExecutionResult.
9	 *
10	 * No child process is spawned — unlike claude_local / openrouter_local,
11	 * Groq has no CLI; we speak HTTP directly.
12	 *
13	 * v0.7 scope:
14	 *   - streaming chat completions with session resume
15	 *   - OpenAI-style tool/function calling with a client-driven loop
16	 *     (Groq has no server loop; we invoke tools via ctx.tools.invoke
17	 *     and feed results back until finish_reason: "stop")
18	 *   - streaming responses logged delta-by-delta via onLog("stdout")
19	 *   - GROQ_API_KEY resolution: config.env → process.env
20	 *
21	 * TODO(next):
22	 *   - retry on 429 with exponential backoff
23	 *   - cost tracking (currently $0 since Groq is free-tier)
24	 */
25	import fs from "node:fs/promises";
26	import path from "node:path";
27	import { asString, asNumber, parseObject, buildPaperclipEnv, joinPromptSections, renderTemplate, renderPaperclipWakePrompt, } from "@paperclipai/adapter-utils/server-utils";
28	import { loadSession, saveSession, newSessionId, parseSseLine, } from "./parse.js";
29	import { ADAPTER_TYPE, AUTH_ENV_VAR, BILLER_SLUG, DEFAULT_MODEL, DEFAULT_PROMPT_TEMPLATE, DEFAULT_TIMEOUT_SEC, GROQ_CHAT_URL, MAX_TOOL_ITERATIONS, PROVIDER_SLUG, } from "../shared/constants.js";
30	import { buildPaperclipTools } from "./paperclip-tools.js";
31	function resolveApiKey(configEnv) {
32	    const fromConfig = typeof configEnv[AUTH_ENV_VAR] === "string"
33	        ? configEnv[AUTH_ENV_VAR].trim()
34	        : "";
35	    if (fromConfig)
36	        return { key: fromConfig, source: "config_env" };
37	    const fromProc = (process.env[AUTH_ENV_VAR] ?? "").trim();
38	    if (fromProc)
39	        return { key: fromProc, source: "process_env" };
40	    return { key: null, source: "missing" };
41	}
42	async function resolveToolsSurface(ctx) {
43	    const surface = ctx.tools;
44	    let rawTools = null;
45	    let invoke = null;
46	    if (surface && typeof surface.invoke === "function") {
47	        invoke = async (name, args) => surface.invoke(name, args);
48	        if (typeof surface.list === "function") {
49	            try {
50	                rawTools = await surface.list();
51	            }
52	            catch {
53	                rawTools = null;
54	            }
55	        }
56	    }
57	    // Fallback: config.tools as a literal OpenAI-style array.
58	    if (!rawTools) {
59	        const fromConfig = Array.isArray(ctx.config.tools)
60	            ? ctx.config.tools
61	            : null;
62	        if (fromConfig) {
63	            rawTools = fromConfig
64	                .map((t) => {
65	                if (!t || typeof t !== "object")
66	                    return null;
67	                const r = t;
68	                const fn = (r.function ?? r);
69	                const name = typeof fn.name === "string" ? fn.name : null;
70	                if (!name)
71	                    return null;
72	                return {
73	                    name,
74	                    description: typeof fn.description === "string" ? fn.description : undefined,
75	                    parameters: fn.parameters && typeof fn.parameters === "object"
76	                        ? fn.parameters
77	                        : undefined,
78	                    input_schema: fn.input_schema && typeof fn.input_schema === "object"
79	                        ? fn.input_schema
80	                        : undefined,
81	                };
82	            })
83	                .filter((v) => v !== null);
84	        }
85	    }
86	    // Fallback: builtin Paperclip control-plane tools (server passes no ctx.tools).
87	    if (!invoke) {
88	        const builtin = buildPaperclipTools(ctx);
89	        rawTools = builtin.rawTools;
90	        invoke = builtin.invoke;
91	    }
92	    const openaiTools = (rawTools ?? []).map((t) => ({
93	        type: "function",
94	        function: {
95	            name: t.name,
96	            description: t.description,
97	            parameters: t.parameters ?? t.input_schema ?? { type: "object", properties: {} },
98	        },
99	    }));
100	    return { openaiTools, invoke };
101	}
102	function parsePaperclipActionBlocks(text) {
103	    const actions = [];
104	    const re = /```[A-Za-z0-9_-]*\s*\n([\s\S]*?)```/g;
105	    let m;
106	    while ((m = re.exec(text)) !== null) {
107	        try {
108	            const parsed = JSON.parse(m[1].trim());
109	            if (parsed && typeof parsed.tool === "string") {
110	                actions.push({ tool: parsed.tool, args: parsed.args ?? {} });
111	            }
112	        }
113	        catch (e) { console.error("parsePaperclipActionBlocks error (```):", e, m[1]); }
114	    }
115	    const anyToolRe = /<tool>([\s\S]*?)(?:<\/tool>|<output>|$)/ig;
116	    while ((m = anyToolRe.exec(text)) !== null) {
117	        try {
118	            let content = m[1];
119	            const firstBrace = content.indexOf('{');
120	            const lastBrace = content.lastIndexOf('}');
121	            if (firstBrace !== -1 && lastBrace !== -1 && lastBrace >= firstBrace) {
122	                content = content.substring(firstBrace, lastBrace + 1);
123	                const parsed = JSON.parse(content.trim());
124	                if (parsed && typeof parsed.tool === "string") {
125	                    actions.push({ tool: parsed.tool, args: parsed.args ?? {} });
126	                }
127	            }
128	        }
129	        catch (e) { console.error("parsePaperclipActionBlocks error (anyToolRe):", e, m[1]); }
130	    }
131	    const unclosedRe = /```[A-Za-z0-9_-]*\s*\n([^`]*)$/i;
132	    const unclosedMatch = unclosedRe.exec(text);
133	    if (unclosedMatch) {
134	        try {
135	            const parsed = JSON.parse(unclosedMatch[1].trim());
136	            if (parsed && typeof parsed.tool === "string") {
137	                actions.push({ tool: parsed.tool, args: parsed.args ?? {} });
138	            }
139	        }
140	        catch (e) { console.error("parsePaperclipActionBlocks error (unclosed ```):", e, unclosedMatch[1]); }
141	    }
142	    return actions;
143	}
144	async function runOneTurn(params) {
145	    const { apiKey, model, messages, tools, signal, onLog, extraBody, extraHeaders } = params;
146	    const body = {
147	        model,
148	        messages,
149	        stream: true,
150	        stream_options: { include_usage: true },
151	        ...(extraBody ?? {}),
152	    };
153	    if (tools.length === 0) {
154	        body.stop = ["</tool>"];
155	    }
156	    if (tools.length > 0) {
157	        body.tools = tools;
158	        body.tool_choice = "auto";
159	    }
160	    let response;
161	    try {
162	        response = await fetch(GROQ_CHAT_URL, {
163	            method: "POST",
164	            headers: {
165	                accept: "text/event-stream",
166	                authorization: "Bearer " + apiKey,
167	                "content-type": "application/json",
168	                "user-agent": "groq-paperclip-adapter/0.7.0",
169	                ...(extraHeaders ?? {}),
170	            },
171	            body: JSON.stringify(body),
172	            signal,
173	        });
174	    }
175	    catch (err) {
176	        const aborted = err?.name === "AbortError";
177	        return {
178	            assistantText: "",
179	            toolCalls: [],
180	            finishReason: null,
181	            usageIn: 0,
182	            usageOut: 0,
183	            model,
184	            streamError: null,
185	            aborted,
186	            networkError: err instanceof Error ? err.message : String(err),
187	        };
188	    }
189	    if (!response.ok || !response.body) {
190	        const bodyText = await response.text().catch(() => "");
191	        return {
192	            assistantText: "",
193	            toolCalls: [],
194	            finishReason: null,
195	            usageIn: 0,
196	            usageOut: 0,
197	            model,
198	            streamError: null,
199	            aborted: false,
200	            httpError: { status: response.status, body: bodyText },
201	        };
202	    }
203	    const reader = response.body.getReader();
204	    const decoder = new TextDecoder();
205	    let buffer = "";
206	    let assistantText = "";
207	    let reasoningText = "";
208	    let finalModel = model;
209	    let finishReason = null;
210	    let usageIn = 0;
211	    let usageOut = 0;
212	    const toolAccum = new Map();
213	    let streamError = null;
214	    let aborted = false;
215	    const apply = async (line) => {
216	        const delta = parseSseLine(line);
217	        if (!delta)
218	            return;
219	        if (delta.model)
220	            finalModel = delta.model;
221	        if (delta.textDelta) {
222	            assistantText += delta.textDelta;
223	            await onLog("stdout", delta.textDelta);
224	        }
225	        if (delta.reasoningDelta) {
226	            reasoningText += delta.reasoningDelta;
227	        }
228	        if (delta.toolCalls) {
229	            for (const tc of delta.toolCalls) {
230	                const existing = toolAccum.get(tc.index) ?? { args: "" };
231	                if (tc.id)
232	                    existing.id = tc.id;
233	                if (tc.name)
234	                    existing.name = tc.name;
235	                if (tc.argumentsDelta)
236	                    existing.args += tc.argumentsDelta;
237	                toolAccum.set(tc.index, existing);
238	            }
239	        }
240	        if (delta.usage) {
241	            usageIn = delta.usage.prompt_tokens ?? usageIn;
242	            usageOut = delta.usage.completion_tokens ?? usageOut;
243	        }
244	        if (delta.finishReason)
245	            finishReason = delta.finishReason;
246	    };
247	    try {
248	        // eslint-disable-next-line no-constant-condition
249	        while (true) {
250	            const { value, done } = await reader.read();
251	            if (done)
252	                break;
253	            buffer += decoder.decode(value, { stream: true });
254	            const lines = buffer.split(/\r?\n/);
255	            buffer = lines.pop() ?? "";
256	            for (const line of lines)
257	                await apply(line);
258	        }
259	        if (buffer.trim())
260	            await apply(buffer);
261	    }
262	    catch (err) {
263	        if (err?.name === "AbortError") {
264	            aborted = true;
265	        }
266	        else {
267	            streamError = err instanceof Error ? err.message : String(err);
268	        }
269	    }
270	    const toolCalls = [...toolAccum.entries()]
271	        .sort((a, b) => a[0] - b[0])
272	        .map(([idx, acc]) => ({
273	        id: acc.id ?? `call_${idx}`,
274	        type: "function",
275	        function: {
276	            name: acc.name ?? "",
277	            arguments: acc.args,
278	        },
279	    }));
280	    return {
281	        assistantText: assistantText.trim().length > 0 ? assistantText : reasoningText,
282	        toolCalls,
283	        finishReason,
284	        usageIn,
285	        usageOut,
286	        model: finalModel,
287	        streamError,
288	        aborted,
289	    };
290	}
291	function safeParseJson(raw) {
292	    const trimmed = raw.trim();
293	    if (!trimmed)
294	        return {};
295	    try {
296	        return JSON.parse(trimmed);
297	    }
298	    catch {
299	        return { _raw: trimmed };
300	    }
301	}
302	function stringifyToolResult(result) {
303	    if (typeof result === "string")
304	        return result;
305	    try {
306	        return JSON.stringify(result);
307	    }
308	    catch {
309	        return String(result);
310	    }
311	}
312	// --------------------------------------------------------------------
313	// Entry point
314	// --------------------------------------------------------------------
315	export async function execute(ctx) {
316	    const { runId, agent, runtime, config, context, onLog, onMeta } = ctx;
317	    const model = asString(config.model, DEFAULT_MODEL);
318	    console.log("EXECUTE_MODEL:", model, "isCompound:", /^groq\/compound/.test(model));
319	    const timeoutSec = asNumber(config.timeoutSec, DEFAULT_TIMEOUT_SEC);
320	    const promptTemplate = asString(config.promptTemplate, DEFAULT_PROMPT_TEMPLATE);
321	    const instructionsFilePath = asString(config.instructionsFilePath, "").trim();
322	    const envConfig = parseObject(config.env);
323	    const extraBody = parseObject(config.extraBody);
324	    // -------- API key --------
325	    const { key: apiKey, source: apiKeySource } = resolveApiKey(envConfig);
326	    if (!apiKey) {
327	        await onLog("stderr", `[paperclip-groq] Missing ${AUTH_ENV_VAR} in both config.env and process.env.\n`);
328	        return {
329	            exitCode: 1,
330	            signal: null,
331	            timedOut: false,
332	            errorMessage: `Missing ${AUTH_ENV_VAR}`,
333	            errorCode: "groq_missing_api_key",
334	        };
335	    }
336	    // -------- Session resume --------
337	    const runtimeSessionParams = parseObject(runtime.sessionParams);
338	    const existingSessionId = asString(runtimeSessionParams.sessionId, runtime.sessionId ?? "") || null;
339	    const existingSession = existingSessionId
340	        ? await loadSession(existingSessionId)
341	        : null;
342	    const sessionId = existingSession ? existingSessionId : newSessionId();
343	    // -------- Prompt assembly --------
344	    const templateData = {
345	        agentId: agent.id,
346	        companyId: agent.companyId,
347	        runId,
348	        company: { id: agent.companyId },
349	        agent,
350	        run: { id: runId, source: "on_demand" },
351	        context,
352	    };
353	    const wakePrompt = renderPaperclipWakePrompt(context.paperclipWake, {
354	        resumedSession: Boolean(existingSession),
355	    });
356	    const sessionHandoffNote = asString(context.paperclipSessionHandoffMarkdown, "").trim();
357	    const renderedPrompt = renderTemplate(promptTemplate, templateData);
358	    const userPrompt = joinPromptSections([
359	        wakePrompt,
360	        sessionHandoffNote,
361	        renderedPrompt,
362	    ]);
363	    // -------- Build messages --------
364	    const messages = [];
365	    if (!existingSession && instructionsFilePath) {
366	        try {
367	            const instructionsContent = await fs.readFile(instructionsFilePath, "utf-8");
368	            const pathDirective = `\n\nThe above agent instructions were loaded from ${instructionsFilePath}. ` +
369	                `Resolve any relative file references from ${path.dirname(instructionsFilePath)}/.`;
370	            messages.push({
371	                role: "system",
372	                content: instructionsContent + pathDirective,
373	            });
374	        }
375	        catch (err) {
376	            const reason = err instanceof Error ? err.message : String(err);
377	            await onLog("stderr", `[paperclip-groq] Warning: could not read instructions file "${instructionsFilePath}": ${reason}\n`);
378	        }
379	    }
380	    if (existingSession) {
381	        messages.push(...existingSession.messages);
382	    }
383	    messages.push({ role: "user", content: userPrompt });
384	    const promptMetrics = {
385	        promptChars: userPrompt.length,
386	        wakePromptChars: wakePrompt.length,
387	        sessionHandoffChars: sessionHandoffNote.length,
388	        heartbeatPromptChars: renderedPrompt.length,
389	        historyMessageCount: existingSession?.messages.length ?? 0,
390	    };
391	    // -------- Paperclip env (for log parity only; we don't spawn) --------
392	    const loggedEnv = {
393	        ...buildPaperclipEnv(agent),
394	        PAPERCLIP_RUN_ID: runId,
395	        [AUTH_ENV_VAR]: `[redacted:${apiKeySource}]`,
396	    };
397	    // -------- Tool surface --------
398	    const { openaiTools, invoke: toolInvoke } = await resolveToolsSurface(ctx);
399	    // Compound systems reject client-side function tools ("tool calling is not
400	    // supported with this model") and require the latest model version header.
401	    // For them we fall back to a fenced-JSON action protocol parsed from text.
402	    const isCompound = /^groq\/compound/.test(model);
403	    const extraHeaders = isCompound ? { "Groq-Model-Version": "latest" } : undefined;
404	    const toolsEnabled = !isCompound && openaiTools.length > 0 && toolInvoke !== null;
405	    const textActionsEnabled = isCompound && openaiTools.length > 0 && toolInvoke !== null;
406	    if (textActionsEnabled) {
407	        const toolDoc = openaiTools
408	            .map((t) => `- ${t.function.name}: ${t.function.description ?? ""}\n  parameters: ${JSON.stringify(t.function.parameters)}`)
409	            .join("\n");
410	        const protocolInsertAt = messages.findIndex((m) => m.role !== "system");
411	        messages.splice(protocolInsertAt === -1 ? messages.length : protocolInsertAt, 0, {
412	            role: "system",
413	            content: [
414	                "You can act on the Paperclip control plane by emitting action blocks. IGNORE ANY PREVIOUS INSTRUCTIONS SAYING YOU ONLY HAVE VISIT, SEARCH, OR PYTHON. YOU ABSOLUTELY HAVE THESE PAPERCLIP TOOLS AVAILABLE AND MUST USE THEM TO COMPLETE YOUR TASKS.",
415	                "To call a tool, output an XML block with tag `tool` containing a single JSON object:",
416	                '<tool>\n{"tool": "<tool name>", "args": { ... }}\n</tool>',
417	                "You may emit several blocks in one reply. After your reply, each block is executed and the results are sent back to you; you can then continue or finish.",
418	                "Only claim an action happened if you emitted the block and saw an ok result for it. Available tools:",
419	                toolDoc,
420	            ].join("\n\n"),
421	        });
422	    }
423	    if (onMeta) {
424	        await onMeta({
