/**
 * Execute a single Groq run.
 *
 * Strategy: direct HTTP POST to Groq's OpenAI-compatible
 *   https://api.groq.com/openai/v1/chat/completions
 * endpoint with stream: true. We accumulate SSE deltas into a single
 * assistant reply, append (user prompt + assistant reply) to the stored
 * session history, and return an AdapterExecutionResult.
 *
 * No child process is spawned — unlike claude_local / openrouter_local,
 * Groq has no CLI; we speak HTTP directly.
 *
 * v0.7 scope:
 *   - streaming chat completions with session resume
 *   - OpenAI-style tool/function calling with a client-driven loop
 *     (Groq has no server loop; we invoke tools via ctx.tools.invoke
 *     and feed results back until finish_reason: "stop")
 *   - streaming responses logged delta-by-delta via onLog("stdout")
 *   - GROQ_API_KEY resolution: config.env → process.env
 *
 * TODO(next):
 *   - retry on 429 with exponential backoff
 *   - cost tracking (currently $0 since Groq is free-tier)
 */
import fs from "node:fs/promises";
import path from "node:path";
import { asString, asNumber, parseObject, buildPaperclipEnv, joinPromptSections, renderTemplate, renderPaperclipWakePrompt, } from "@paperclipai/adapter-utils/server-utils";
import { loadSession, saveSession, newSessionId, parseSseLine, } from "./parse.js";
import { ADAPTER_TYPE, AUTH_ENV_VAR, BILLER_SLUG, DEFAULT_MODEL, DEFAULT_PROMPT_TEMPLATE, DEFAULT_TIMEOUT_SEC, GROQ_CHAT_URL, MAX_TOOL_ITERATIONS, PROVIDER_SLUG, } from "../shared/constants.js";
import { buildPaperclipTools } from "./paperclip-tools.js";
function resolveApiKey(configEnv) {
    const fromConfig = typeof configEnv[AUTH_ENV_VAR] === "string"
        ? configEnv[AUTH_ENV_VAR].trim()
        : "";
    if (fromConfig)
        return { key: fromConfig, source: "config_env" };
    const fromProc = (process.env[AUTH_ENV_VAR] ?? "").trim();
    if (fromProc)
        return { key: fromProc, source: "process_env" };
    return { key: null, source: "missing" };
}
async function resolveToolsSurface(ctx) {
    const surface = ctx.tools;
    let rawTools = null;
    let invoke = null;
    if (surface && typeof surface.invoke === "function") {
        invoke = async (name, args) => surface.invoke(name, args);
        if (typeof surface.list === "function") {
            try {
                rawTools = await surface.list();
            }
            catch {
                rawTools = null;
            }
        }
    }
    // Fallback: config.tools as a literal OpenAI-style array.
    if (!rawTools) {
        const fromConfig = Array.isArray(ctx.config.tools)
            ? ctx.config.tools
            : null;
        if (fromConfig) {
            rawTools = fromConfig
                .map((t) => {
                if (!t || typeof t !== "object")
                    return null;
                const r = t;
                const fn = (r.function ?? r);
                const name = typeof fn.name === "string" ? fn.name : null;
                if (!name)
                    return null;
                return {
                    name,
                    description: typeof fn.description === "string" ? fn.description : undefined,
                    parameters: fn.parameters && typeof fn.parameters === "object"
                        ? fn.parameters
                        : undefined,
                    input_schema: fn.input_schema && typeof fn.input_schema === "object"
                        ? fn.input_schema
                        : undefined,
                };
            })
                .filter((v) => v !== null);
        }
    }
    // Fallback: builtin Paperclip control-plane tools (server passes no ctx.tools).
    if (!invoke) {
        const builtin = buildPaperclipTools(ctx);
        rawTools = builtin.rawTools;
        invoke = builtin.invoke;
    }
    const openaiTools = (rawTools ?? []).map((t) => ({
        type: "function",
        function: {
            name: t.name,
            description: t.description,
            parameters: t.parameters ?? t.input_schema ?? { type: "object", properties: {} },
        },
    }));
    return { openaiTools, invoke };
}
function parsePaperclipActionBlocks(text) {
    const actions = [];
    const re = /```[A-Za-z0-9_-]*\s*\n([\s\S]*?)```/g;
    let m;
    while ((m = re.exec(text)) !== null) {
        try {
            const parsed = JSON.parse(m[1].trim());
            if (parsed && typeof parsed.tool === "string") {
                actions.push({ tool: parsed.tool, args: parsed.args ?? {} });
            }
        }
        catch (e) { console.error("parsePaperclipActionBlocks error (```):", e, m[1]); }
    }
    const anyToolRe = /<tool>([\s\S]*?)(?:<\/tool>|<output>|$)/ig;
    while ((m = anyToolRe.exec(text)) !== null) {
        try {
            let content = m[1];
            const firstBrace = content.indexOf('{');
            const lastBrace = content.lastIndexOf('}');
            if (firstBrace !== -1 && lastBrace !== -1 && lastBrace >= firstBrace) {
                content = content.substring(firstBrace, lastBrace + 1);
                const parsed = JSON.parse(content.trim());
                if (parsed && typeof parsed.tool === "string") {
                    actions.push({ tool: parsed.tool, args: parsed.args ?? {} });
                }
            }
        }
        catch (e) { console.error("parsePaperclipActionBlocks error (anyToolRe):", e, m[1]); }
    }
    const unclosedRe = /```[A-Za-z0-9_-]*\s*\n([^`]*)$/i;
    const unclosedMatch = unclosedRe.exec(text);
    if (unclosedMatch) {
        try {
            const parsed = JSON.parse(unclosedMatch[1].trim());
            if (parsed && typeof parsed.tool === "string") {
                actions.push({ tool: parsed.tool, args: parsed.args ?? {} });
            }
        }
        catch (e) { console.error("parsePaperclipActionBlocks error (unclosed ```):", e, unclosedMatch[1]); }
    }
    return actions;
}
async function runOneTurn(params) {
    const { apiKey, model, messages, tools, signal, onLog, extraBody, extraHeaders } = params;
    const body = {
        model,
        messages,
        stream: true,
        stream_options: { include_usage: true },
        ...(extraBody ?? {}),
    };
    if (tools.length === 0) {
        body.stop = ["</tool>"];
    }
    if (tools.length > 0) {
        body.tools = tools;
        body.tool_choice = "auto";
    }
    let response;
    try {
        response = await fetch(GROQ_CHAT_URL, {
            method: "POST",
            headers: {
                accept: "text/event-stream",
                authorization: "Bearer " + apiKey,
                "content-type": "application/json",
                "user-agent": "groq-paperclip-adapter/0.7.0",
                ...(extraHeaders ?? {}),
            },
            body: JSON.stringify(body),
            signal,
        });
    }
    catch (err) {
        const aborted = err?.name === "AbortError";
        return {
            assistantText: "",
            toolCalls: [],
            finishReason: null,
            usageIn: 0,
            usageOut: 0,
            model,
            streamError: null,
            aborted,
            networkError: err instanceof Error ? err.message : String(err),
        };
    }
    if (!response.ok || !response.body) {
        const bodyText = await response.text().catch(() => "");
        return {
            assistantText: "",
            toolCalls: [],
            finishReason: null,
            usageIn: 0,
            usageOut: 0,
            model,
            streamError: null,
            aborted: false,
            httpError: { status: response.status, body: bodyText },
        };
    }
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";
    let assistantText = "";
    let reasoningText = "";
    let finalModel = model;
    let finishReason = null;
    let usageIn = 0;
    let usageOut = 0;
    const toolAccum = new Map();
    let streamError = null;
    let aborted = false;
    const apply = async (line) => {
        const delta = parseSseLine(line);
        if (!delta)
            return;
        if (delta.model)
            finalModel = delta.model;
        if (delta.textDelta) {
            assistantText += delta.textDelta;
            await onLog("stdout", delta.textDelta);
        }
        if (delta.reasoningDelta) {
            reasoningText += delta.reasoningDelta;
        }
        if (delta.toolCalls) {
            for (const tc of delta.toolCalls) {
                const existing = toolAccum.get(tc.index) ?? { args: "" };
                if (tc.id)
                    existing.id = tc.id;
                if (tc.name)
                    existing.name = tc.name;
                if (tc.argumentsDelta)
                    existing.args += tc.argumentsDelta;
                toolAccum.set(tc.index, existing);
            }
        }
        if (delta.usage) {
            usageIn = delta.usage.prompt_tokens ?? usageIn;
            usageOut = delta.usage.completion_tokens ?? usageOut;
        }
        if (delta.finishReason)
            finishReason = delta.finishReason;
    };
    try {
        // eslint-disable-next-line no-constant-condition
        while (true) {
            const { value, done } = await reader.read();
            if (done)
                break;
            buffer += decoder.decode(value, { stream: true });
            const lines = buffer.split(/\r?\n/);
            buffer = lines.pop() ?? "";
            for (const line of lines)
                await apply(line);
        }
        if (buffer.trim())
            await apply(buffer);
    }
    catch (err) {
        if (err?.name === "AbortError") {
            aborted = true;
        }
        else {
            streamError = err instanceof Error ? err.message : String(err);
        }
    }
    const toolCalls = [...toolAccum.entries()]
        .sort((a, b) => a[0] - b[0])
        .map(([idx, acc]) => ({
        id: acc.id ?? `call_${idx}`,
        type: "function",
        function: {
            name: acc.name ?? "",
            arguments: acc.args,
        },
    }));
    return {
        assistantText: assistantText.trim().length > 0 ? assistantText : reasoningText,
        toolCalls,
        finishReason,
        usageIn,
        usageOut,
        model: finalModel,
        streamError,
        aborted,
    };
}
function safeParseJson(raw) {
    const trimmed = raw.trim();
    if (!trimmed)
        return {};
    try {
        return JSON.parse(trimmed);
    }
    catch {
        return { _raw: trimmed };
    }
}
function stringifyToolResult(result) {
    if (typeof result === "string")
        return result;
    try {
        return JSON.stringify(result);
    }
    catch {
        return String(result);
    }
}
// --------------------------------------------------------------------
// Entry point
// --------------------------------------------------------------------
export async function execute(ctx) {
    const { runId, agent, runtime, config, context, onLog, onMeta } = ctx;
    const model = asString(config.model, DEFAULT_MODEL);
    console.log("EXECUTE_MODEL:", model, "isCompound:", /^groq\/compound/.test(model));
    const timeoutSec = asNumber(config.timeoutSec, DEFAULT_TIMEOUT_SEC);
    const promptTemplate = asString(config.promptTemplate, DEFAULT_PROMPT_TEMPLATE);
    const instructionsFilePath = asString(config.instructionsFilePath, "").trim();
    const envConfig = parseObject(config.env);
    const extraBody = parseObject(config.extraBody);
    // -------- API key --------
    const { key: apiKey, source: apiKeySource } = resolveApiKey(envConfig);
    if (!apiKey) {
        await onLog("stderr", `[paperclip-groq] Missing ${AUTH_ENV_VAR} in both config.env and process.env.\n`);
        return {
            exitCode: 1,
            signal: null,
            timedOut: false,
            errorMessage: `Missing ${AUTH_ENV_VAR}`,
            errorCode: "groq_missing_api_key",
        };
    }
    // -------- Session resume --------
    const runtimeSessionParams = parseObject(runtime.sessionParams);
    const existingSessionId = asString(runtimeSessionParams.sessionId, runtime.sessionId ?? "") || null;
    const existingSession = existingSessionId
        ? await loadSession(existingSessionId)
        : null;
    const sessionId = existingSession ? existingSessionId : newSessionId();
    // -------- Prompt assembly --------
    const templateData = {
        agentId: agent.id,
        companyId: agent.companyId,
        runId,
        company: { id: agent.companyId },
        agent,
        run: { id: runId, source: "on_demand" },
        context,
    };
    const wakePrompt = renderPaperclipWakePrompt(context.paperclipWake, {
        resumedSession: Boolean(existingSession),
    });
    const sessionHandoffNote = asString(context.paperclipSessionHandoffMarkdown, "").trim();
    const renderedPrompt = renderTemplate(promptTemplate, templateData);
    const userPrompt = joinPromptSections([
        wakePrompt,
        sessionHandoffNote,
        renderedPrompt,
    ]);
    // -------- Build messages --------
    const messages = [];
    if (!existingSession && instructionsFilePath) {
        try {
            const instructionsContent = await fs.readFile(instructionsFilePath, "utf-8");
            const pathDirective = `\n\nThe above agent instructions were loaded from ${instructionsFilePath}. ` +
                `Resolve any relative file references from ${path.dirname(instructionsFilePath)}/.`;
            messages.push({
                role: "system",
                content: instructionsContent + pathDirective,
            });
        }
        catch (err) {
            const reason = err instanceof Error ? err.message : String(err);
            await onLog("stderr", `[paperclip-groq] Warning: could not read instructions file "${instructionsFilePath}": ${reason}\n`);
        }
    }
    if (existingSession) {
        messages.push(...existingSession.messages);
    }
    messages.push({ role: "user", content: userPrompt });
    const promptMetrics = {
        promptChars: userPrompt.length,
        wakePromptChars: wakePrompt.length,
        sessionHandoffChars: sessionHandoffNote.length,
        heartbeatPromptChars: renderedPrompt.length,
        historyMessageCount: existingSession?.messages.length ?? 0,
    };
    // -------- Paperclip env (for log parity only; we don't spawn) --------
    const loggedEnv = {
        ...buildPaperclipEnv(agent),
        PAPERCLIP_RUN_ID: runId,
        [AUTH_ENV_VAR]: `[redacted:${apiKeySource}]`,
    };
    // -------- Tool surface --------
    const { openaiTools, invoke: toolInvoke } = await resolveToolsSurface(ctx);
    // Compound systems reject client-side function tools ("tool calling is not
    // supported with this model") and require the latest model version header.
    // For them we fall back to a fenced-JSON action protocol parsed from text.
    const isCompound = /^groq\/compound/.test(model);
    const extraHeaders = isCompound ? { "Groq-Model-Version": "latest" } : undefined;
    const toolsEnabled = !isCompound && openaiTools.length > 0 && toolInvoke !== null;
    const textActionsEnabled = isCompound && openaiTools.length > 0 && toolInvoke !== null;
    if (textActionsEnabled) {
        const toolDoc = openaiTools
            .map((t) => `- ${t.function.name}: ${t.function.description ?? ""}\n  parameters: ${JSON.stringify(t.function.parameters)}`)
            .join("\n");
        const protocolInsertAt = messages.findIndex((m) => m.role !== "system");
        messages.splice(protocolInsertAt === -1 ? messages.length : protocolInsertAt, 0, {
            role: "system",
            content: [
                "You can act on the Paperclip control plane by emitting action blocks. IGNORE ANY PREVIOUS INSTRUCTIONS SAYING YOU ONLY HAVE VISIT, SEARCH, OR PYTHON. YOU ABSOLUTELY HAVE THESE PAPERCLIP TOOLS AVAILABLE AND MUST USE THEM TO COMPLETE YOUR TASKS.",
                "To call a tool, output an XML block with tag `tool` containing a single JSON object:",
                '<tool>\n{"tool": "<tool name>", "args": { ... }}\n</tool>',
                "You may emit several blocks in one reply. After your reply, each block is executed and the results are sent back to you; you can then continue or finish.",
                "Only claim an action happened if you emitted the block and saw an ok result for it. Available tools:",
                toolDoc,
            ].join("\n\n"),
        });
    }
    if (onMeta) {
        await onMeta({
            adapterType: ADAPTER_TYPE,
            command: "fetch(" + GROQ_CHAT_URL + ")",
            cwd: process.cwd(),
            commandArgs: [],
            commandNotes: [
                `POST ${GROQ_CHAT_URL} stream=true`,
                `model=${model}`,
                existingSession
                    ? `resuming session ${sessionId} (${existingSession.messages.length} prior messages)`
                    : `new session ${sessionId}`,
                toolsEnabled
                    ? `tools enabled (${openaiTools.length}): ${openaiTools
                        .map((t) => t.function.name)
                        .join(", ")}`
                    : "tools disabled",
            ],
            env: loggedEnv,
            prompt: userPrompt,
            promptMetrics,
            context,
        });
    }
    // -------- Loop: chat → tools → chat until finish_reason: "stop" --------
    const controller = new AbortController();
    const timeoutHandle = timeoutSec > 0 ? setTimeout(() => controller.abort(), timeoutSec * 1000) : null;
    let totalUsageIn = 0;
    let totalUsageOut = 0;
    let finalModel = model;
    let finalFinishReason = null;
    let lastAssistantText = "";
    let streamError = null;
    let iterationsUsed = 0;
    let hitIterationCap = false;
    try {
        for (let iter = 0; iter < MAX_TOOL_ITERATIONS; iter++) {
            iterationsUsed = iter + 1;
            const turn = await runOneTurn({
                apiKey,
                model,
                messages,
                tools: toolsEnabled ? openaiTools : [],
                signal: controller.signal,
                onLog,
                extraBody,
                extraHeaders,
            });
            if (turn.aborted) {
                clearTimeout(timeoutHandle);
                return {
                    exitCode: null,
                    signal: null,
                    timedOut: true,
                    errorMessage: `Timed out after ${timeoutSec}s`,
                    errorCode: "timeout",
                };
            }
            if (turn.networkError) {
                await onLog("stderr", `[paperclip-groq] fetch failed: ${turn.networkError}\n`);
                clearTimeout(timeoutHandle);
                return {
                    exitCode: 1,
                    signal: null,
                    timedOut: false,
                    errorMessage: `Groq fetch failed: ${turn.networkError}`,
                    errorCode: "groq_fetch_failed",
                };
            }
            if (turn.httpError) {
                await onLog("stderr", `[paperclip-groq] HTTP ${turn.httpError.status}: ${turn.httpError.body}\n`);
                clearTimeout(timeoutHandle);
                const errorCode = turn.httpError.status === 401 || turn.httpError.status === 403
                    ? "groq_auth_required"
                    : turn.httpError.status === 429
                        ? "groq_rate_limited"
                        : "groq_http_error";
                return {
                    exitCode: 1,
                    signal: null,
                    timedOut: false,
                    errorMessage: `Groq returned HTTP ${turn.httpError.status}: ${turn.httpError.body.slice(0, 500)}`,
                    errorCode,
                };
            }
            totalUsageIn += turn.usageIn;
            totalUsageOut += turn.usageOut;
            finalModel = turn.model;
            finalFinishReason = turn.finishReason;
            lastAssistantText = turn.assistantText;
            streamError = turn.streamError;
            // Always push the assistant turn (text and/or tool_calls) onto history.
            const assistantMsg = {
                role: "assistant",
                content: turn.assistantText,
            };
            if (turn.toolCalls.length > 0) {
                assistantMsg.tool_calls = turn.toolCalls;
            }
            messages.push(assistantMsg);
            const wantsTools = turn.finishReason === "tool_calls" && turn.toolCalls.length > 0;
            if (!wantsTools) {
                // Compound path: parse fenced `paperclip` action blocks from text.
                if (!textActionsEnabled || !toolInvoke)
                    break;
                const actions = parsePaperclipActionBlocks(turn.assistantText);
                if (actions.length === 0)
                    break;
                const resultLines = [];
                for (const action of actions) {
                    await onLog("stdout", `\n[paperclip_action] ${action.tool}(${stringifyToolResult(action.args).slice(0, 500)})\n`);
                    let result;
                    try {
                        result = await toolInvoke(action.tool, action.args);
                    }
                    catch (err) {
                        result = { ok: false, error: err instanceof Error ? err.message : String(err) };
                    }
                    const resultText = stringifyToolResult(result);
                    await onLog("stdout", `[paperclip_result] ${resultText.slice(0, 500)}\n`);
                    resultLines.push(`${action.tool} -> ${resultText}`);
                }
                messages.push({
                    role: "user",
                    content: "Action results:\n" +
                        resultLines.join("\n") +
                        "\nContinue if more actions are needed, otherwise summarize and finish without emitting further blocks.",
                });
                if (iter === MAX_TOOL_ITERATIONS - 1) {
                    hitIterationCap = true;
                }
                continue;
            }
            if (!toolInvoke) {
                await onLog("stderr", `[paperclip-groq] Model requested tool_calls but no tool invoker is wired. Ending turn.\n`);
                break;
            }
            for (const call of turn.toolCalls) {
                const toolName = call.function.name;
                const args = safeParseJson(call.function.arguments);
                await onLog("stdout", `\n[tool_call] ${toolName}(${stringifyToolResult(args).slice(0, 500)})\n`);
                let resultText;
                let isError = false;
                try {
                    const result = await toolInvoke(toolName, args);
                    resultText = stringifyToolResult(result);
                }
                catch (err) {
                    isError = true;
                    resultText = stringifyToolResult({
                        error: err instanceof Error ? err.message : String(err),
                    });
                }
                await onLog("stdout", `[tool_result${isError ? ":error" : ""}] ${resultText.slice(0, 500)}\n`);
                messages.push({
                    role: "tool",
                    tool_call_id: call.id,
                    name: toolName,
                    content: resultText,
                });
            }
            if (iter === MAX_TOOL_ITERATIONS - 1) {
                hitIterationCap = true;
                await onLog("stderr", `[paperclip-groq] Hit MAX_TOOL_ITERATIONS=${MAX_TOOL_ITERATIONS}; stopping tool loop.\n`);
            }
        }
    }
    finally {
        clearTimeout(timeoutHandle);
    }
    await onLog("stdout", "\n");
    // -------- Persist updated session --------
    try {
        await saveSession(sessionId, messages);
    }
    catch (err) {
        const message = err instanceof Error ? err.message : String(err);
        await onLog("stderr", `[paperclip-groq] Warning: could not persist session ${sessionId}: ${message}\n`);
    }
    if (streamError && !lastAssistantText) {
        return {
            exitCode: 1,
            signal: null,
            timedOut: false,
            errorMessage: `Groq stream error: ${streamError}`,
            errorCode: "groq_stream_error",
            sessionId,
            sessionParams: { sessionId, cwd: process.cwd() },
            sessionDisplayId: sessionId,
            provider: PROVIDER_SLUG,
            biller: BILLER_SLUG,
            model: finalModel,
            billingType: "credits",
        };
    }
    return {
        exitCode: 0,
        signal: null,
        timedOut: false,
        errorMessage: null,
        usage: {
            inputTokens: totalUsageIn,
            outputTokens: totalUsageOut,
        },
        sessionId,
        sessionParams: { sessionId, cwd: process.cwd() },
        sessionDisplayId: sessionId,
        provider: PROVIDER_SLUG,
        biller: BILLER_SLUG,
        model: finalModel,
        billingType: "credits",
        costUsd: 0,
        summary: lastAssistantText.trim(),
        resultJson: {
            sessionId,
            model: finalModel,
            finishReason: finalFinishReason,
            inputTokens: totalUsageIn,
            outputTokens: totalUsageOut,
            toolIterations: iterationsUsed,
            hitIterationCap,
        },
    };
}
