function parsePaperclipActionBlocks(text) {
    const actions = [];
    const re = /```[A-Za-z0-9_-]*\s*\n([\s\S]*?)```/g;
    let m;
    while ((m = re.exec(text)) !== null) {
        try {
            const parsed = JSON.parse(m[1].trim());
            if (parsed && typeof parsed.tool === "string") {
                actions.push({ tool: parsed.tool, args: parsed.args ?? {} });
            }
        }
        catch (e) { console.error("parsePaperclipActionBlocks error (```):", e, m[1]); }
    }
    const anyToolRe = /<tool>([\s\S]*?)(?:<\/tool>|<output>|$)/ig;
    while ((m = anyToolRe.exec(text)) !== null) {
        try {
            let content = m[1];
            const firstBrace = content.indexOf('{');
            const lastBrace = content.lastIndexOf('}');
            if (firstBrace !== -1 && lastBrace !== -1 && lastBrace >= firstBrace) {
                content = content.substring(firstBrace, lastBrace + 1);
                const parsed = JSON.parse(content.trim());
                if (parsed && typeof parsed.tool === "string") {
                    actions.push({ tool: parsed.tool, args: parsed.args ?? {} });
                }
            }
        }
        catch (e) { console.error("parsePaperclipActionBlocks error (anyToolRe):", e, m[1]); }
    }
    const unclosedRe = /```[A-Za-z0-9_-]*\s*\n([^`]*)$/i;
    const unclosedMatch = unclosedRe.exec(text);
    if (unclosedMatch) {
        try {
            const parsed = JSON.parse(unclosedMatch[1].trim());
            if (parsed && typeof parsed.tool === "string") {
                actions.push({ tool: parsed.tool, args: parsed.args ?? {} });
            }
        }
        catch (e) { console.error("parsePaperclipActionBlocks error (unclosed ```):", e, unclosedMatch[1]); }
    }
    return actions;
}

input.new_string:
function parsePaperclipActionBlocks(text) {
    // Single-pass extraction with span masking + dedupe. The old version ran
    // three overlapping regexes over the same text, so one <tool> block inside
    // a code fence executed 2-3x (this is how duplicate agents got created).
    const actions = [];
    const seen = new Set();
    let working = text;
    const pushAction = (raw) => {
        const firstBrace = raw.indexOf("{");
        const lastBrace = raw.lastIndexOf("}");
        const content = firstBrace !== -1 && lastBrace >= firstBrace
            ? raw.substring(firstBrace, lastBrace + 1)
            : raw;
        let parsed;
        try {
            parsed = JSON.parse(content.trim());
        }
        catch {
            return false;
        }
        if (!parsed || typeof parsed.tool !== "string")
            return false;
        const key = JSON.stringify({ tool: parsed.tool, args: parsed.args ?? {} });
        if (seen.has(key))
            return true; // recognized, but duplicate — swallow it
        seen.add(key);
        actions.push({ tool: parsed.tool, args: parsed.args ?? {} });
        return true;
    };
    // Pass 1: <tool>…</tool> blocks (closing tag may be missing — the stream
    // is stopped on "</tool>", or the model forgot it).
    const toolTagRe = /<tool>([\s\S]*?)(?:<\/tool>|<output>|$)/gi;
    working = working.replace(toolTagRe, (_full, inner) => {
        pushAction(String(inner));
        return "\n";
    });
    // Pass 2: fenced code blocks on the remaining (masked) text.
    const fenceRe = /```[A-Za-z0-9_-]*\s*\n([\s\S]*?)```/g;
    working = working.replace(fenceRe, (_full, inner) => {
        pushAction(String(inner));
        return "\n";
    });
    // Pass 3: trailing unclosed fence on whatever is left.
    const unclosedMatch = /```[A-Za-z0-9_-]*\s*\n([^`]*)$/i.exec(working);
    if (unclosedMatch)
        pushAction(unclosedMatch[1]);
    return actions;
}

