1	/**
2	 * External adapter plugin loader.
3	 *
4	 * Loads external adapter packages from the adapter-plugin-store and returns
5	 * their ServerAdapterModule instances. The caller (registry.ts) is
6	 * responsible for registering them.
7	 *
8	 * This avoids circular initialization: plugin-loader imports only
9	 * adapter-utils, never registry.ts.
10	 */
11	
12	import fs from "node:fs";
13	import path from "node:path";
14	import type { ServerAdapterModule } from "./types.js";
15	import { logger } from "../middleware/logger.js";
16	
17	import {
18	  listAdapterPlugins,
19	  getAdapterPluginsDir,
20	  getAdapterPluginByType,
21	} from "../services/adapter-plugin-store.js";
22	import type { AdapterPluginRecord } from "../services/adapter-plugin-store.js";
23	
24	// ---------------------------------------------------------------------------
25	// In-memory UI parser cache
26	// ---------------------------------------------------------------------------
27	
28	const uiParserCache = new Map<string, string>();
29	
30	export function getUiParserSource(adapterType: string): string | undefined {
31	  return uiParserCache.get(adapterType);
32	}
33	
34	/**
35	 * On cache miss, attempt on-demand extraction from the plugin store.
36	 * Makes the ui-parser.js endpoint self-healing.
37	 */
38	export function getOrExtractUiParserSource(adapterType: string): string | undefined {
39	  const cached = uiParserCache.get(adapterType);
40	  if (cached) return cached;
41	
42	  const record = getAdapterPluginByType(adapterType);
43	  if (!record) return undefined;
44	
45	  const packageDir = resolvePackageDir(record);
46	  const source = extractUiParserSource(packageDir, record.packageName);
47	  if (source) {
48	    uiParserCache.set(adapterType, source);
49	    logger.info(
50	      { type: adapterType, packageName: record.packageName, origin: "lazy" },
51	      "UI parser extracted on-demand (cache miss)",
52	    );
53	  }
54	  return source;
55	}
56	
57	// ---------------------------------------------------------------------------
58	// Shared helpers
59	// ---------------------------------------------------------------------------
60	
61	function resolvePackageDir(record: Pick<AdapterPluginRecord, "localPath" | "packageName">): string {
62	  return record.localPath
63	    ? path.resolve(record.localPath)
64	    : path.resolve(getAdapterPluginsDir(), "node_modules", record.packageName);
65	}
66	
67	function resolvePackageEntryPoint(packageDir: string): string {
68	  const pkgJsonPath = path.join(packageDir, "package.json");
69	  const pkg = JSON.parse(fs.readFileSync(pkgJsonPath, "utf-8"));
70	
71	  if (pkg.exports && typeof pkg.exports === "object" && pkg.exports["."]) {
72	    const exp = pkg.exports["."];
73	    return typeof exp === "string" ? exp : (exp.import ?? exp.default ?? "index.js");
74	  }
75	  return pkg.main ?? "index.js";
76	}
77	
78	// ---------------------------------------------------------------------------
79	// UI parser extraction
80	// ---------------------------------------------------------------------------
81	
82	const SUPPORTED_PARSER_CONTRACT = "1";
83	
84	function extractUiParserSource(
85	  packageDir: string,
86	  packageName: string,
87	): string | undefined {
88	  const pkgJsonPath = path.join(packageDir, "package.json");
89	  const pkg = JSON.parse(fs.readFileSync(pkgJsonPath, "utf-8"));
90	
91	  if (!pkg.exports || typeof pkg.exports !== "object" || !pkg.exports["./ui-parser"]) {
92	    return undefined;
93	  }
94	
95	  const contractVersion = pkg.paperclip?.adapterUiParser;
96	  if (contractVersion) {
97	    const major = contractVersion.split(".")[0];
98	    if (major !== SUPPORTED_PARSER_CONTRACT) {
99	      logger.warn(
100	        { packageName, contractVersion, supported: `${SUPPORTED_PARSER_CONTRACT}.x` },
101	        "Adapter declares unsupported UI parser contract version — skipping UI parser",
102	      );
103	      return undefined;
104	    }
105	  } else {
