            label: "Timeout (seconds)",
            type: "number",
            default: DEFAULT_TIMEOUT_SEC,
            required: false,
        },
        {
            key: "promptTemplate",
            label: "Prompt template",
            type: "textarea",
            default: DEFAULT_PROMPT_TEMPLATE,
            required: false,
        },
        {
            key: "instructionsFilePath",
            label: "Instructions file path (AGENTS.md)",
            type: "text",
            default: "",
            required: false,
