/**
 * Factory invoked by the Paperclip plugin loader.
 */
export function createServerAdapter() {
    return {
        type: ADAPTER_TYPE,
        execute,
        testEnvironment,
        sessionCodec,
        models,
        agentConfigurationDoc,
        detectModel,
        getConfigSchema: () => configSchema,
        supportsInstructionsBundle: true,
