// ---------------------------------------------------------------------
// Workspace tools — file read/write/list and command execution, rooted
// at the issue's project workspace (context.paperclipWorkspace.cwd).
// Only exposed when a workspace directory is resolvable.
// ---------------------------------------------------------------------
const wsContext = ctx.context && typeof ctx.context === "object"
    ? (ctx.context.paperclipWorkspace ?? {})
    : {};
const workspaceCwd = typeof wsContext.cwd === "string" && wsContext.cwd.trim()
    ? wsContext.cwd.trim()
    : (typeof ctx.config?.cwd === "string" && ctx.config.cwd.trim() ? ctx.config.cwd.trim() : "");
if (workspaceCwd) {
    const root = nodePath.resolve(workspaceCwd);
    const resolveInRoot = (p) => {
        const abs = nodePath.resolve(root, String(p ?? "."));
        if (abs !== root && !abs.startsWith(root + nodePath.sep)) {
            throw new Error(`Path escapes the project workspace: ${p}`);
        }
        return abs;
    };
    const MAX_READ_CHARS = 50_000;
    const MAX_CMD_OUTPUT = 20_000;
    tools.push({
        name: "read_file",
        description: "Read a text file from the project workspace. Path is relative to the workspace root.",
        parameters: {
            type: "object",
            properties: {
                path: { type: "string" },
                offset: { type: "number", description: "1-based start line (optional)" },
                limit: { type: "number", description: "Max lines to return (optional)" },
            },
            required: ["path"],
        },
        run: async (args) => {
            const abs = resolveInRoot(args.path);
            let content = await fsp.readFile(abs, "utf-8");
            if (args.offset || args.limit) {
                const lines = content.split("\n");
                const start = Math.max(0, (args.offset ?? 1) - 1);
                const end = args.limit ? start + args.limit : lines.length;
                content = lines.slice(start, end).join("\n");
            }
            const truncated = content.length > MAX_READ_CHARS;
            return {
                ok: true,
                path: nodePath.relative(root, abs),
                content: truncated ? content.slice(0, MAX_READ_CHARS) : content,
                truncated,
            };
        },
    }, {
        name: "write_file",
        description: "Write (create or overwrite) a text file in the project workspace. Path is relative to the workspace root. Parent directories are created automatically.",
        parameters: {
            type: "object",
            properties: {
                path: { type: "string" },
                content: { type: "string" },
            },
            required: ["path", "content"],
        },
        run: async (args) => {
            const abs = resolveInRoot(args.path);
            await fsp.mkdir(nodePath.dirname(abs), { recursive: true });
            await fsp.writeFile(abs, String(args.content ?? ""), "utf-8");
            return { ok: true, path: nodePath.relative(root, abs), bytes: Buffer.byteLength(String(args.content ?? "")) };
        },
    }, {
        name: "list_dir",
        description: "List files and directories in the project workspace. Path is relative to the workspace root; defaults to the root.",
        parameters: {
            type: "object",
            properties: { path: { type: "string" } },
        },
        run: async (args) => {
            const abs = resolveInRoot(args.path ?? ".");
            const entries = await fsp.readdir(abs, { withFileTypes: true });
            return {
                ok: true,
                path: nodePath.relative(root, abs) || ".",
                entries: entries
                    .filter((e) => e.name !== ".git" && e.name !== "node_modules")
                    .slice(0, 200)
                    .map((e) => ({ name: e.name, type: e.isDirectory() ? "dir" : "file" })),
            };
        },
    }, {
        name: "run_command",
        description: "Run a shell command in the project workspace (cwd = workspace root). Returns stdout, stderr and exit code. Use for builds, tests, git, etc.",
        parameters: {
            type: "object",
            properties: {
                command: { type: "string" },
                timeoutSec: { type: "number", description: "Timeout in seconds, default 60, max 300" },
            },
            required: ["command"],
        },
        run: async (args) => {
            const timeoutMs = Math.min(Math.max(Number(args.timeoutSec) || 60, 1), 300) * 1000;
            return await new Promise((resolvePromise) => {
                exec(String(args.command), { cwd: root, timeout: timeoutMs, maxBuffer: 10 * 1024 * 1024 }, (err, stdout, stderr) => {
                    resolvePromise({
                        ok: !err,
                        exitCode: err && typeof err.code === "number" ? err.code : err ? 1 : 0,
                        timedOut: Boolean(err && err.killed),
                        stdout: String(stdout ?? "").slice(0, MAX_CMD_OUTPUT),
                        stderr: String(stderr ?? "").slice(0, MAX_CMD_OUTPUT),
                    });
                });
            });
        },
    });
}

