21	export function getNextIssuesPageOffset(
22	  loadedPageSize: number,
23	  currentOffset: number,
24	  pageSize: number = ISSUES_PAGE_SIZE,
25	): number | undefined {
26	  return loadedPageSize >= pageSize ? currentOffset + pageSize : undefined;
27	}
