29	export function mergeIssuePagesStable(pages: Issue[][]): Issue[] {
30	  const seenIssueIds = new Set<string>();
31	  const merged: Issue[] = [];
32	
33	  for (const page of pages) {
34	    for (const issue of page) {
35	      if (seenIssueIds.has(issue.id)) continue;
36	      seenIssueIds.add(issue.id);
37	      merged.push(issue);
38	    }
39	  }
40	
41	  return merged;
42	}
