44	export function buildIssuesSearchUrl(currentHref: string, search: string): string | null {
45	  const url = new URL(currentHref);
46	  const currentSearch = url.searchParams.get("q") ?? "";
47	  if (currentSearch === search) return null;
48	
49	  if (search.length > 0) {
50	    url.searchParams.set("q", search);
51	  } else {
52	    url.searchParams.delete("q");
53	  }
54	
55	  return `${url.pathname}${url.search}${url.hash}`;
56	}
