            // Dedupe guard: never create a second agent with the same name.
            const existing = await call("GET", `/api/companies/${agent.companyId}/agents`);
            if (existing.ok && Array.isArray(existing.result)) {
                const dup = existing.result.find((a) => typeof a.name === "string" &&
                    a.name.trim().toLowerCase() === String(args.name).trim().toLowerCase());
                if (dup) {
                    return {
                        ok: true,
                        agent: { id: dup.id, name: dup.name, role: dup.role },
                        note: "An agent with this name already exists; reusing it instead of creating a duplicate.",
                    };
