let noActionNudgeUsed = false;
try {
    for (let iter = 0; iter < MAX_TOOL_ITERATIONS; iter++) {
        iterationsUsed = iter + 1;
        const turn = await runOneTurn({
            apiKey,
            model,
            messages,
            tools: toolsEnabled ? openaiTools : [],
            signal: controller.signal,
            onLog,
            extraBody,
            extraHeaders,
        });
        if (turn.aborted) {
            clearTimeout(timeoutHandle);
            return {
                exitCode: null,
                signal: null,
                timedOut: true,
                errorMessage: `Timed out after ${timeoutSec}s`,
                errorCode: "timeout",
            };
        }
        if (turn.networkError) {
            await onLog("stderr", `[paperclip-groq] fetch failed: ${turn.networkError}\n`);
            clearTimeout(timeoutHandle);
            return {
                exitCode: 1,
                signal: null,
                timedOut: false,
                errorMessage: `Groq fetch failed: ${turn.networkError}`,
                errorCode: "groq_fetch_failed",
            };
        }
        if (turn.httpError) {
            await onLog("stderr", `[paperclip-groq] HTTP ${turn.httpError.status}: ${turn.httpError.body}\n`);
            clearTimeout(timeoutHandle);
            const errorCode = turn.httpError.status === 401 || turn.httpError.status === 403
                ? "groq_auth_required"
                : turn.httpError.status === 429
                    ? "groq_rate_limited"
                    : "groq_http_error";
            return {
                exitCode: 1,
                signal: null,
                timedOut: false,
                errorMessage: `Groq returned HTTP ${turn.httpError.status}: ${turn.httpError.body.slice(0, 500)}`,
                errorCode,
            };
        }
        totalUsageIn += turn.usageIn;
        totalUsageOut += turn.usageOut;
        finalModel = turn.model;
        finalFinishReason = turn.finishReason;
        lastAssistantText = turn.assistantText;
        streamError = turn.streamError;
        // Always push the assistant turn (text and/or tool_calls) onto history.
        const assistantMsg = {
            role: "assistant",
            content: turn.assistantText,
        };
        if (turn.toolCalls.length > 0) {
            assistantMsg.tool_calls = turn.toolCalls;
        }

