// Retry budget for 429s across the whole run (not per turn).
let rateLimitRetriesLeft = 4;
const sleep = (ms) => new Promise((r) => {
    const t = setTimeout(r, ms);
    controller.signal.addEventListener("abort", () => { clearTimeout(t); r(); }, { once: true });
});
try {
    for (let iter = 0; iter < MAX_TOOL_ITERATIONS; iter++) {
        iterationsUsed = iter + 1;
        let turn = await runOneTurn({
            apiKey,
            model,
            messages,
            tools: toolsEnabled ? openaiTools : [],
            signal: controller.signal,
            onLog,
            extraBody,
            extraHeaders,
        });
        // 429: honor retry-after (or exponential backoff) instead of
        // failing the run — failed runs trigger recovery retries that
        // burn even more quota.
        while (turn.httpError?.status === 429 &&
            rateLimitRetriesLeft > 0 &&
            !controller.signal.aborted) {
            const attempt = 5 - rateLimitRetriesLeft;
            rateLimitRetriesLeft--;
            const headerSec = turn.httpError.retryAfterSec;
            const waitSec = Number.isFinite(headerSec) && headerSec > 0
                ? Math.min(headerSec, 120)
                : Math.min(10 * 2 ** attempt, 120);
            await onLog("stderr", `[paperclip-groq] HTTP 429 (rate limited); waiting ${waitSec}s then retrying (${rateLimitRetriesLeft} retries left).\n`);
            await sleep(waitSec * 1000);
            if (controller.signal.aborted)
                break;
            turn = await runOneTurn({
                apiKey,
                model,
                messages,
                tools: toolsEnabled ? openaiTools : [],
                signal: controller.signal,
                onLog,
                extraBody,
                extraHeaders,
