// execute only the first and tell the model the rest were
// ignored so it re-issues them deliberately, one at a time.
const ignoredActions = actions.slice(1);
actions.length = 1;
if (ignoredActions.length > 0) {
    resultLines.push(`NOTE: you emitted ${ignoredActions.length + 1} action blocks but only ONE is allowed per reply. Only the first (${actions[0].tool}) was executed. Ignored: ${ignoredActions.map((a) => a.tool).join(", ")}. Re-emit them one per reply if still needed.`);
}
for (const action of actions) {
    await onLog("stdout", `\n[paperclip_action] ${action.tool}(${stringifyToolResult(action.args).slice(0, 500)})\n`);
    let result;
    try {
        result = await toolInvoke(action.tool, action.args);
    }
    catch (err) {
        result = { ok: false, error: err instanceof Error ? err.message : String(err) };
    }
    actionsExecuted++;
    if (action.tool === "paperclip_update_issue_status" && result && result.ok !== false) {
        dispositionRecorded = true;
    }
    const resultText = stringifyToolResult(result);
    await onLog("stdout", `[paperclip_result] ${resultText.slice(0, 500)}\n`);
    resultLines.push(`${action.tool} -> ${resultText}`);
}
messages.push({
