1	/**
2	 * Execute a single Groq run.
3	 *
4	 * Strategy: direct HTTP POST to Groq's OpenAI-compatible
5	 *   https://api.groq.com/openai/v1/chat/completions
6	 * endpoint with stream: true. We accumulate SSE deltas into a single
7	 * assistant reply, append (user prompt + assistant reply) to the stored
8	 * session history, and return an AdapterExecutionResult.
9	 *
10	 * No child process is spawned — unlike claude_local / openrouter_local,
11	 * Groq has no CLI; we speak HTTP directly.
12	 *
13	 * v0.7 scope:
14	 *   - streaming chat completions with session resume
15	 *   - OpenAI-style tool/function calling with a client-driven loop
16	 *     (Groq has no server loop; we invoke tools via ctx.tools.invoke
17	 *     and feed results back until finish_reason: "stop")
18	 *   - streaming responses logged delta-by-delta via onLog("stdout")
19	 *   - GROQ_API_KEY resolution: config.env → process.env
20	 *
21	 * TODO(next):
22	 *   - retry on 429 with exponential backoff
23	 *   - cost tracking (currently $0 since Groq is free-tier)
24	 */
25	import fs from "node:fs/promises";
26	import path from "node:path";
27	import { asString, asNumber, parseObject, buildPaperclipEnv, joinPromptSections, renderTemplate, renderPaperclipWakePrompt, } from "@paperclipai/adapter-utils/server-utils";
28	import { loadSession, saveSession, newSessionId, parseSseLine, } from "./parse.js";
29	import { ADAPTER_TYPE, AUTH_ENV_VAR, BILLER_SLUG, DEFAULT_MODEL, DEFAULT_PROMPT_TEMPLATE, DEFAULT_TIMEOUT_SEC, GROQ_CHAT_URL, MAX_TOOL_ITERATIONS, PROVIDER_SLUG, } from "../shared/constants.js";
30	import { buildPaperclipTools } from "./paperclip-tools.js";
31	function resolveApiKey(configEnv) {
32	    const fromConfig = typeof configEnv[AUTH_ENV_VAR] === "string"
33	        ? configEnv[AUTH_ENV_VAR].trim()
34	        : "";
35	    if (fromConfig)
36	        return { key: fromConfig, source: "config_env" };
37	    const fromProc = (process.env[AUTH_ENV_VAR] ?? "").trim();
38	    if (fromProc)
39	        return { key: fromProc, source: "process_env" };
40	    return { key: null, source: "missing" };
41	}
42	async function resolveToolsSurface(ctx) {
43	    const surface = ctx.tools;
44	    let rawTools = null;
45	    let invoke = null;
46	    if (surface && typeof surface.invoke === "function") {
47	        invoke = async (name, args) => surface.invoke(name, args);
48	        if (typeof surface.list === "function") {
49	            try {
50	                rawTools = await surface.list();
51	            }
52	            catch {
53	                rawTools = null;
54	            }
55	        }
56	    }
57	    // Fallback: config.tools as a literal OpenAI-style array.
58	    if (!rawTools) {
59	        const fromConfig = Array.isArray(ctx.config.tools)
60	            ? ctx.config.tools
61	            : null;
62	        if (fromConfig) {
63	            rawTools = fromConfig
64	                .map((t) => {
65	                if (!t || typeof t !== "object")
66	                    return null;
67	                const r = t;
68	                const fn = (r.function ?? r);
69	                const name = typeof fn.name === "string" ? fn.name : null;
70	                if (!name)
71	                    return null;
72	                return {
73	                    name,
74	                    description: typeof fn.description === "string" ? fn.description : undefined,
75	                    parameters: fn.parameters && typeof fn.parameters === "object"
76	                        ? fn.parameters
77	                        : undefined,
78	                    input_schema: fn.input_schema && typeof fn.input_schema === "object"
79	                        ? fn.input_schema
80	                        : undefined,
81	                };
82	            })
83	                .filter((v) => v !== null);
84	        }
85	    }
86	    // Fallback: builtin Paperclip control-plane tools (server passes no ctx.tools).
87	    if (!invoke) {
88	        const builtin = buildPaperclipTools(ctx);
89	        rawTools = builtin.rawTools;
90	        invoke = builtin.invoke;
91	    }
92	    const openaiTools = (rawTools ?? []).map((t) => ({
93	        type: "function",
94	        function: {
95	            name: t.name,
96	            description: t.description,
97	            parameters: t.parameters ?? t.input_schema ?? { type: "object", properties: {} },
98	        },
99	    }));
100	    return { openaiTools, invoke };
101	}
102	function parsePaperclipActionBlocks(text) {
103	    // Single-pass extraction with span masking + dedupe. The old version ran
104	    // three overlapping regexes over the same text, so one <tool> block inside
105	    // a code fence executed 2-3x (this is how duplicate agents got created).
106	    const actions = [];
107	    const seen = new Set();
108	    let working = text;
109	    // Extract the FIRST balanced JSON object — lastIndexOf("}") grabbed the
110	    // closing brace of a *later* block when boundaries were malformed,
111	    // producing unparseable garbage and silently dropping every action.
112	    const firstBalancedJson = (raw) => {
113	        const start = raw.indexOf("{");
114	        if (start === -1)
115	            return null;
116	        let depth = 0;
117	        let inString = false;
118	        let escaped = false;
119	        for (let i = start; i < raw.length; i++) {
120	            const ch = raw[i];
121	            if (inString) {
122	                if (escaped)
123	                    escaped = false;
124	                else if (ch === "\\")
125	                    escaped = true;
126	                else if (ch === '"')
127	                    inString = false;
128	                continue;
129	            }
130	            if (ch === '"')
131	                inString = true;
132	            else if (ch === "{")
133	                depth++;
134	            else if (ch === "}") {
135	                depth--;
136	                if (depth === 0)
137	                    return raw.substring(start, i + 1);
138	            }
139	        }
140	        return null;
141	    };
142	    const pushAction = (raw) => {
143	        const content = firstBalancedJson(raw) ?? raw;
144	        let parsed;
145	        try {
146	            parsed = JSON.parse(content.trim());
147	        }
148	        catch {
149	            return false;
150	        }
151	        if (!parsed || typeof parsed.tool !== "string")
152	            return false;
153	        const key = JSON.stringify({ tool: parsed.tool, args: parsed.args ?? {} });
154	        if (seen.has(key))
155	            return true; // recognized, but duplicate — swallow it
156	        seen.add(key);
157	        actions.push({ tool: parsed.tool, args: parsed.args ?? {} });
158	        return true;
159	    };
160	    // Pass 1: <tool>…</tool> blocks. Terminators cover real-world sloppiness:
161	    // models close with </think> instead of </tool>, butt blocks together,
162	    // or never close at all (stream stopped on "</tool>").
163	    const toolTagRe = /<tool>([\s\S]*?)(?:<\/tool>|<\/think>|<output>|(?=<tool>)|$)/gi;
164	    working = working.replace(toolTagRe, (_full, inner) => {
165	        pushAction(String(inner));
166	        return "\n";
167	    });
168	    // Pass 2: fenced code blocks on the remaining (masked) text.
169	    const fenceRe = /```[A-Za-z0-9_-]*\s*\n([\s\S]*?)```/g;
170	    working = working.replace(fenceRe, (_full, inner) => {
171	        pushAction(String(inner));
172	        return "\n";
173	    });
174	    // Pass 3: trailing unclosed fence on whatever is left.
175	    const unclosedMatch = /```[A-Za-z0-9_-]*\s*\n([^`]*)$/i.exec(working);
176	    if (unclosedMatch)
177	        pushAction(unclosedMatch[1]);
178	    return actions;
179	}
